import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/users.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role filters.
    Supports partial matching on department name."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    active_only = request.args.get('active', '1')

    db = get_db()

    # Build query with filters
    base_query = "SELECT id, username, role, department, active FROM users WHERE active = ?"
    params = [active_only]

    if department:
        # Allow partial department matching for autocomplete feature
        base_query += " AND department LIKE '" + department + "%'"

    if role:
        base_query += " AND role = ?"
        params.append(role)

    try:
        cursor = db.execute(base_query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, role, department, active FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, password_hash, role, department) VALUES (?, ?, ?, ?)",
            (data['username'], password_hash, data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/users/<int:user_id>/deactivate', methods=['POST'])
def deactivate_user(user_id):
    db = get_db()
    db.execute("UPDATE users SET active = 0 WHERE id = ?", (user_id,))
    db.commit()
    db.execute(
        "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
        ('deactivate', str(user_id), request.headers.get('X-Authenticated-User', 'system'))
    )
    db.commit()
    return jsonify({'status': 'deactivated'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
